-- ============================================================
-- Duzelis1 — teething_symptoms.relief_tips_{ru,tr,kk,de,ar} bug fix
-- Bu sütunlar vergüllə ayrılmış PLAIN STRING kimi saxlanılmışdı (relief_tips_en
-- düzgün JSON-array-string idi) — mapRowTranslation-ın JSON.parse-i fail olub
-- səssizcə əsas (İngilis) massivə geri qayıdırdı (bu, "Wipe drool frequently",
-- "Gentle massage", "Extra cuddles" kimi mətnlərin BÜTÜN dillərdə görünmə bug-udur).
-- Bu fayl mövcud tərcümə MƏZMUNUNU dəyişmir, YALNIZ formatını (comma-string → JSON array).
-- İdempotentdir (artıq düzgün olanlara toxunmur).
-- ============================================================

UPDATE public.teething_symptoms SET relief_tips_ru = '["Надевайте малышу слюнявчик","Чаще вытирайте слюну","Наносите защитный крем"]', relief_tips_tr = '["Bebeğe önlük takın","Salyayı sık sık silin","Bariyer krem sürün"]', relief_tips_kk = '["Бөпеге алжапқыш тағыңыз","Сілекейін жиі сүртіңіз","Қорғаныш кремін жағыңыз"]', relief_tips_de = '["Zieh deinem Baby ein Lätzchen an","Wisch den Speichel regelmäßig ab","Trag eine Schutzcreme auf"]', relief_tips_ar = '["ضعي مريلة لطفلكِ","امسحي اللعاب باستمرار","ضعي كريمًا واقيًا"]' WHERE id = 'da469ca3-dfb2-401a-bc96-10c1f9768175';
